// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data. The rejection's message is the
// server's own `error` text when it sent one.
//
// Every request carries the signed-in name in X-User (the server records it as `by=<user>`), and,
// while this screen shows the sheet as of a date, that date in X-As-Of: reads answer as the sheet stood
// then, and every change is refused.
let signedInUser = '';
let asOfDate = '';

/** A non-2xx answer: the server's message, and its status (409 when someone else saved first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** Called by the session (features/session) whenever the signed-in name changes. */
export function setSignedInUser(name: string): void {
  signedInUser = name;
}

/** Called by the as-of control (features/asof) whenever the screen's as-of date changes ('' when none). */
export function setAsOfDate(date: string): void {
  asOfDate = date;
}

/** The as-of date requests are sent with ('' when none). */
export function currentAsOfDate(): string {
  return asOfDate;
}

async function send<T>(path: string, init?: RequestInit, asOf = asOfDate): Promise<T> {
  const headers = new Headers(init?.headers);
  if (signedInUser) headers.set('X-User', signedInUser);
  if (asOf) headers.set('X-As-Of', asOf);
  const res = await fetch(path, { ...init, headers });
  if (!res.ok) {
    let message = `${init?.method ?? 'GET'} ${path} -> ${res.status}`;
    try {
      const body = (await res.json()) as { error?: string };
      if (body?.error) message = body.error;
    } catch {
      /* no JSON body: keep the status message */
    }
    throw new HttpError(message, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

/** A read that answers as the store holds the sheet now, whatever date this screen shows it as of. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path, undefined, '');
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { settingOn, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
 *  claims dated within one of their holds left out unless a statement binds them; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
 *  A due-total is at most the sheet's cap in force on its today ('n/a' is not capped). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
  return totals;
}

/** Each person's excess, by person id: how far the sum of their figures is above the sheet's cap; 0.00 when
 *  it is not (or there is no cap, or their due-total is 'n/a'). */
export function useExcess(sheetId: string): Map<number, string> {
  const excess = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
  return excess;
}

/** Each person's settled-total and open-total, by person id: the sum of the figures of their counting SETTLED
 *  claims, and of their counting open (OPEN or PENDING) claims, as in their due-total ('n/a' figures skipped).
 *  The two add up to the due-total before the cap. */
export function useSettledOpenTotals(sheetId: string): Map<number, { settled: string; open: string }> {
  const split = new Map<number, { settled: string; open: string }>();
  for (const [id, f] of useDueFigures(sheetId)) split.set(id, { settled: f.settled, open: f.open });
  return split;
}

/** Each person's due-total held to the cap, their excess over it, and its settled and open parts. */
function useDueFigures(sheetId: string): Map<number, { total: string; excess: string; settled: string; open: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  const holds = holdsById(people.data, today.data?.today);
  const cap = settingOn(settings, 'cap', today.data?.today);
  const totals = new Map<number, { total: string; excess: string; settled: string; open: string }>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, holds, today.data?.today));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today.data?.today, gradeOn(p, c.date)));
    const shown = rated || counting.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
    const sum = sumDues(dues);
    const over = shown && cap !== null && hundredths(sum) > hundredths(cap);
    totals.set(p.id, {
      total: !shown ? 'n/a' : over ? cap : sum,
      excess: over ? money(hundredths(sum) - hundredths(cap)) : '0.00',
      settled: sumDues(dues.filter((_, i) => counting[i].status === 'SETTLED')),
      open: sumDues(dues.filter((_, i) => counting[i].status !== 'SETTLED')),
    });
  }
  return totals;
}
import { counts, fixedDue, isDeferred, isOpen, useClaims, type Claim } from '../claims/useClaims';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { atLeast, due, isCorrection, rateFor, sumDues, useRates, withCharge } from '../rates/useRates';
import { settingOn, useSettings, type Settings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

/** The day (yyyy-mm-dd) a claim's overdue days count from: its due-by plus the grace days, in force on the claim's
 *  date, of the grade its person had on that date (`grade`); its due-by when that grade has none then. */
export function overdueFrom(c: Claim, settings: Settings | undefined, grade: string | undefined): string {
  const grace = grade === undefined ? null : settingOn(settings, `grace-${grade}`, c.date);
  if (grace === null || grace === '') return c.dueBy;
  return new Date(Date.parse(`${c.dueBy}T00:00:00Z`) + Number(grace) * 86_400_000).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its overdue-from day (see
 *  `overdueFrom`; `grade` is the grade its person had on its date) is before the sheet's today. */
export function isOverdue(c: Claim, today: string, settings: Settings | undefined, grade: string | undefined): boolean {
  return isOpen(c) && !isDeferred(c, today) && overdueFrom(c, settings, grade) < today;
}

/** Whether a claim's live figures (its rate step and late charge) round half up: when the claim is
 *  dated before the sheet's policy date (blank meaning the sheet's today); else they round half to
 *  even. A correction rounds by the date of the claim it corrects (its person's claim with that
 *  number), not its own. Half to even until the settings and the sheet's today are loaded. */
export function roundsHalfUp(c: Claim, claims: Claim[] | undefined, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
  if (policy === undefined) return false;
  const corrected = c.corrects === null
    ? undefined
    : (claims ?? []).find((o) => o.personId === c.personId && o.number === c.corrects);
  return (corrected?.date ?? c.date) < policy;
}

/** A claim's due now: a settled claim's frozen due; else the greater of the floor (two decimals; none while
 *  it is not loaded) and its figure (the one its last statement bound it to, else its live rate figure) plus,
 *  while it is overdue, for every full 30 days it is overdue the sheet's late percent in force on that boundary
 *  date (the overdue-from day — the due-by plus the grade's grace — plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up. The
 *  charge is never bound by a statement: it follows the sheet's today until settling freezes it in. A correction
 *  (a negative amount) has no floor and no late charge. No charge until the settings and the sheet's today are loaded. */
export function dueNow(c: Claim, figure: string, floor: string | undefined, settings: Settings | undefined,
  today: string | undefined, halfUp: boolean, grade: string | undefined): string {
  if (c.due !== null || figure === 'n/a' || isCorrection(c.amount)) return figure;
