export const GRADES = ['A', 'B', 'C'] as const;

export function peopleKey(sheetId: string) {
  return ['sheet', sheetId, 'people'];
}

/** The sheet's people, the patrons they have named, the people the signed-in user watches, their aliases and the
 *  people whose name or an alias is already a name or alias on another sheet of the tree, as the store holds them. */
type PeopleBody = { people: Person[]; patrons: Patron[]; watched: number[]; aliases: Alias[]; clashing: number[] };

function peopleBody(sheetId: string): Promise<PeopleBody> {
  return getJson<PeopleBody>(`/api/sheets/${encodeURIComponent(sheetId)}/people`);
}

/** Read the sheet's people from the store. */
export async function fetchPeople(sheetId: string): Promise<Person[]> {
  return (await peopleBody(sheetId)).people;
}

export function patronsKey(sheetId: string) {
  return [...peopleKey(sheetId), 'patrons'];
export function retiredOn(person: Person, today: string | undefined): boolean {
  return person.retiredFrom !== null && today !== undefined && person.retiredFrom <= today;
}

/** The sheet's people, in list order. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => fetchPeople(sheetId),
  });
}
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () => {
      const res = await getJson<{
        claims: Omit<Claim, 'log' | 'comments' | 'lockedBy' | 'batch'>[];
        logs: Record<string, string[]>;
        locks: Record<string, string>;
        comments: Record<string, string[]>;
        batches: Record<string, number>;
      }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`);
      return res.claims.map((c): Claim => ({
        ...c,
        log: res.logs[String(c.id)] ?? [],
        comments: res.comments[String(c.id)] ?? [],
        lockedBy: res.locks[String(c.id)] ?? null,
        batch: res.batches[String(c.id)] ?? null,
      }));
    },
  });
}

/** Every tag ever used on the sheet, sorted. Kept under the claims' key, so whatever re-reads the claims
  return ['sheet', sheetId, 'rates'];
}

/** The sheet's rates (level 0), by grade then from-date (an undated rate first); a grade with no rate is not
 *  listed. Then those of the sheets its grades fall back to, nearest first (level 1 its parent, up to 3). */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () => {
      const got = await getJson<{ rates: Rate[]; inherited: Rate[][] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`);
      return [
        ...got.rates.map((r) => ({ ...r, level: 0 })),
        ...(got.inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 }))),
      ];
    },
  });
}

/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): on this sheet, the one with
 *  the latest from-date on or before it, an undated rate applying from the beginning of time, unless the date is
 *  after that rate's to-date; when this sheet has none in force, its parent's the same way, then the parent's
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type SheetToday = { id: string; today: string; archived: boolean };

/** The sheet's today (yyyy-mm-dd), and whether it is archived. Every date decision and default date in a sheet uses this,
 *  never the browser's clock. */
export function useSheetToday(sheetId: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'today'],
    queryFn: () => getJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`),
  });
